-- List databases with size, owner, and encoding
SELECT datname,
       pg_size_pretty(pg_database_size(datname)) AS size,
       pg_encoding_to_char(encoding) AS encoding,
       datcollate, pg_get_userbyid(datdba) AS owner
FROM pg_database
ORDER BY pg_database_size(datname) DESC;

-- Rename (cannot rename the database you are currently connected to)
ALTER DATABASE app_development RENAME TO app_dev;

-- Change owner
ALTER DATABASE app_dev OWNER TO app_admin;

-- Prevent new connections and terminate existing ones before a migration
ALTER DATABASE app_dev ALLOW_CONNECTIONS false;
SELECT pg_terminate_backend(pid)
FROM pg_stat_activity
WHERE datname = 'app_dev' AND pid <> pg_backend_pid();
